STUB="const window=globalThis;const values=new Map(),session=new Map();let quota=false;const localStorage={getItem:k=>values.get(k)||null,setItem:(k,v)=>{if(quota)throw Error('Storage full');values.set(k,v)}};const sessionStorage={getItem:k=>session.get(k)||null};const crypto={randomUUID:(()=>{let n=0;return ()=>'level-'+(++n)})()};const legacy={version:1,title:'Our original course',tiles:Array.from({length:16},(_,y)=>Array(60).fill(y>=14?'ground':'')),start:{x:2,y:13},goal:{x:56,y:13}};legacy.tiles[11][6]='milkbrick';localStorage.setItem('jumpWorkshop',JSON.stringify(legacy));"
TESTS="function assert(v,m){if(!v)throw Error(m)}const s=StoryWorld;let w=s.load();assert(w.levels.length===3,'initial chapters');assert(w.levels[1].level.tiles[0].length===720,'generated story chapters are 12 times longer');assert(w.levels.at(-1).level.tiles[13][710]==='','final boss arena has no overlapping fish');const first=w.levels[0].id;assert(w.levels[0].level.tiles[11][6]==='milkbrick','legacy course preserved');assert(values.get('jumpWorkshop')===JSON.stringify(legacy),'legacy backup untouched');s.complete(first);assert(s.chapter(first).complete,'completion star');let edited=s.chapter(first).level;edited.tiles[10][6]='coin';s.saveLevel(first,edited);assert(!s.chapter(first).complete,'edited course resets completion');const newId=s.add({...legacy,title:'Chapter four'});assert(s.get().levels.length===4,'multiple saved levels');s.move(newId,-1);assert(s.get().levels[2].id===newId,'reorder chapters');s.updateChapter(newId,'New name','A story about milk');assert(s.chapter(newId).story==='A story about milk','chapter story');s.updateStory('Our family story','An adventure begins');assert(s.get().title==='Our family story','world title');const backup=JSON.parse(JSON.stringify(s.get()));assert(s.valid(backup),'whole story backup validates');s.remove(newId);assert(s.get().levels.length===3,'delete chapter');s.replace(backup);assert(s.get().levels.length===4&&s.chapter(newId).story==='A story about milk','backup restores chapters and story');const invalid=JSON.parse(JSON.stringify(backup));invalid.levels[1].id=invalid.levels[0].id;assert(!s.valid(invalid),'duplicate ids rejected');const invalidTile=JSON.parse(JSON.stringify(legacy));invalidTile.tiles[0][0]='anything';assert(!s.validLevel(invalidTile),'invalid tiles rejected');s.select(newId);assert(s.get().selected===newId,'selection saved');s.complete(first);s.resetProgress();assert(s.get().levels.every(c=>!c.complete),'reset progress keeps chapters');quota=true;let rejected=false;try{s.updateStory('Lost','Lost')}catch{rejected=true}assert(rejected&&s.get().title==='Our family story','storage failures preserve prior state');quota=false;assert(JSON.parse(values.get(s.key)).title==='Our family story','saved copy not lost');s.remove(newId);while(s.get().levels.length>1)s.remove(s.get().levels.at(-1).id);rejected=false;try{s.remove(first)}catch{rejected=true}assert(rejected&&s.get().levels.length===1,'cannot delete last chapter');'Story migration, level library, ordering, completion, backup restore and storage failure checks passed';"

TESTS += "\nconst a=s.add({...legacy,title:'Path A'}),b=s.add({...legacy,title:'Path B'});let m=s.get().map;assert(m.nodes.length===3&&s.next(first)===a,'new levels receive map markers and default paths');m.customPaths=true;m.links.push({from:first,to:b});m.decorations.push({id:'tree-1',kind:'tree',x:400,y:300});s.updateMap(m);assert(s.exits(first).length===2,'branching chapter exits');s.move(b,-1);assert(s.exits(first).length===2,'reordering retains custom paths');m=s.get().map;m.nodes[0].x=350;m.reference='data:image/jpeg;base64,YQ==';s.updateMap(m);assert(s.get().map.nodes[0].x===350&&s.get().map.reference,'positions and drawing saved');s.remove(a);assert(s.exits(first).length===1&&s.next(first)===b,'deleting a level removes orphan paths');m=s.get().map;m.nodes[0].x=-5;let badMap=false;try{s.updateMap(m)}catch{badMap=true}assert(badMap,'invalid map positions rejected');'Story persistence, portable map layout, branching paths, drawings, and level deletion checks passed';\n"
