TESTS += "\nconst styled=s.get().levels[0].id;s.complete(styled);s.saveLevel(styled,{...s.chapter(styled).level,style:'world'});assert(s.chapter(styled).level.style==='world','a course keeps its game style');assert(s.chapter(styled).complete,'changing only the style keeps the completion star');assert(s.load().levels.find(c=>c.id===styled).level.style==='world','game style survives reloading');'Story persistence, portable map layout, branching paths, drawings, level deletion, marker spacing, backup size and game style checks passed';\n"
TESTS += "\nconst novel=s.chapter(styled).level;for(const [i,t] of ['pipe','plant','turtle','fish','firebrick','icebrick','tanukibrick','raccoon','switch','redblock','blueblock'].entries())novel.tiles[8][i]=t;novel.theme='underwater';assert(s.validLevel(novel),'new tiles and underwater theme validate');s.saveLevel(styled,novel);assert(s.chapter(styled).level.theme==='underwater'&&s.chapter(styled).level.tiles[8][6]==='tanukibrick','new level features survive save');assert(s.chapter(styled).level.tiles[8][7]==='raccoon'&&s.chapter(styled).level.tiles[8][10]==='blueblock','raccoons and switch blocks survive save');assert(!s.validLevel({...novel,theme:'house'}),'the boss room is never saved as a chapter');const reloaded=JSON.parse(values.get(s.key));assert(reloaded.levels.find(c=>c.id===styled).level.theme==='underwater','underwater theme survives reload');assert(s.validLevel({...novel,theme:undefined}),'old ground courses remain valid');assert(!s.validLevel({...novel,theme:'space'}),'unknown theme rejected');s.complete(styled);s.saveLevel(styled,{...novel,theme:'ground'});assert(!s.chapter(styled).complete,'changing the physics theme clears completion');'Story checks passed, including new tiles, themes and old-save compatibility';\n"
TESTS += "\nconst long={...legacy,tiles:legacy.tiles.map((row,y)=>row.concat(Array(660).fill(y>=14?'ground':''))),goal:{x:716,y:13}};assert(s.validLevel(long),'720-tile course validates');s.saveLevel(styled,long);assert(s.chapter(styled).level.goal.x===716&&s.chapter(styled).level.tiles[0].length===720,'long course saves');assert(JSON.parse(values.get(s.key)).levels.find(c=>c.id===styled).level.tiles[0].length===720,'long course reloads');const ragged={...long,tiles:long.tiles.map(r=>r.slice())};ragged.tiles[0].pop();assert(!s.validLevel(ragged),'ragged course rejected');const oversized={...long,tiles:long.tiles.map(r=>r.concat(''))};assert(!s.validLevel(oversized),'course over 720 tiles rejected');assert(s.validLevel(legacy),'old 60-tile course still valid');'Story checks passed, including long courses and old saves';\n"
